'use client'

import axiosInstance from '@/api/axiosInstance';
import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';

export default function ResourceDetail() {
  const { id } = useParams();
  const [resource, setResource] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchResource = async () => {
      try {
        const response = await axiosInstance.get(`/api/resources/${id}`);
        setResource(response.data);
      } catch (error) {
        setError(error);
      } finally {
        setLoading(false);
      }
    };

    if (id) fetchResource();
  }, [id]);

  if (loading) return (
    <div className="flex justify-center items-center min-h-screen">
      <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (error) return (
    <div className="text-center text-red-600 mt-20">
      <p>Error loading resource.</p>
    </div>
  );

  if (!resource) return null;

  const postDate = new Date(resource.createdAt).toLocaleDateString(undefined, {
    year: 'numeric', month: 'long', day: 'numeric'
  });

  return (
    <main className="max-w-4xl mx-auto px-6 py-12">
      {resource.coverImage && (
        <img
          src={resource.coverImage}
          alt={`Cover image for ${resource.title}`}
          className="w-full h-64 object-cover rounded-lg mb-8 shadow-md"
        />
      )}
      <article className="prose prose-lg max-w-none">
        <h1 className="font-extrabold text-gray-900">{resource.title}</h1>
        <div className="flex flex-col sm:flex-row sm:items-center justify-between mt-2 mb-6 text-gray-500 text-sm">
          <span>By <strong className="text-gray-700">{resource.author}</strong></span>
          <span>{postDate}</span>
        </div>

        {resource.description && (
          <p className="text-gray-700 mb-8">{resource.description}</p>
        )}

        <section className="whitespace-pre-line text-gray-800 leading-relaxed" style={{whiteSpace: 'pre-line'}}>
          {resource.content}
        </section>
      </article>
    </main>
  );
}
